/// Shared "generated by / do not edit" banner embedded as an XML comment in
/// every XML file this package writes (Android drawables/styles.xml, iOS
/// LaunchScreen.storyboard). Not used for `Contents.json` — JSON has no
/// comment syntax; that file signals ownership via its `info.author` field
/// instead.
const generatedNoticeXmlComment =
    '<!-- GENERATED by pure_native_splash. DO NOT EDIT — this file is '
    'regenerated and overwritten every time '
    '`dart run pure_native_splash:create` runs. -->';
